  page.route(re.compile(r'/src/lib/ipc\.ts(?:\?.*)?$'),route);page.goto(a.url,wait_until='networkidle');page.get_by_role('button',name='Try typed text',exact=True).click();trial=page.locator('dialog').last;trial.get_by_role('combobox').select_option('builtin.raw');trial.get_by_label('Your text',exact=True).fill(source);trial.get_by_role('button',name='Try this text',exact=True).click();editor=trial.get_by_label('Result text',exact=True);expect(editor).to_have_value(source);trial.get_by_role('button',name='Wording options',exact=True).click();panel=trial.get_by_role('region',name='Request wording',exact=True);expect(panel.get_by_role('button',name='Use this wording',exact=True)).to_have_count(2);expect(panel).to_contain_text('Local options need no text-service account');expect(panel.get_by_role('button',name='Ask text service for alternatives',exact=True)).to_be_disabled();checks.append('Raw/default path exposes real local options without text-service configuration; cloud action disabled and setup distinction visible')
  panel.get_by_role('button',name='Use this wording',exact=True).last.click();changed=source.replace('could you send','would you be able to send');expect(editor).to_have_value(changed);expect(trial.get_by_label('Your text',exact=True)).to_have_value(source);trial.get_by_role('button',name='Save draft',exact=True).click();expect(trial.get_by_role('button',name='Saved draft',exact=True)).to_be_disabled();calls=page.evaluate('window.__keylessCalls');save=[x['args'] for x in calls if x['cmd']=='save_text_draft'][-1];assert save['original']==source and save['text']==changed;assert not any(x['cmd']=='suggest_polite_text_edits' for x in calls);assert all(x['args']['stylePackId']=='builtin.raw' for x in calls if x['cmd']=='try_style_pack_text');checks.append('actual122 Hi-prefixed failure edits only request span: greeting,Friday,remainder preserved; explicit softer choice and Save keep original, zero cloud suggestion request')
